import type { CartService } from '../core/port'
import type { RuntimeContext } from '../core/runtime'
import type { CartDTO, CartLineDTO } from '../core/types'
import { computeSubtotal, quantityIssue } from '../core/math'

export interface MockCatalogItem {
  sku: string
  name: string
  variant?: string
  /** Minor units. */
  unitPrice: number
}

export interface MockPromo {
  code: string
  percentOff: number
}

const DEFAULT_CATALOG: MockCatalogItem[] = [
  { sku: 'sku-filter', name: 'Whole-home water filter', unitPrice: 89900 },
  { sku: 'sku-softener', name: 'Water softener system', variant: '40,000 grain', unitPrice: 129900 },
  { sku: 'sku-uv', name: 'UV purifier add-on', unitPrice: 34900 },
  { sku: 'sku-cartridge', name: 'Replacement cartridge (2-pack)', unitPrice: 4900 },
]

const DEFAULT_PROMOS: MockPromo[] = [
  { code: 'SAVE10', percentOff: 10 },
  { code: 'WELCOME5', percentOff: 5 },
]

export interface MockCartServiceOptions {
  latencyMs?: number
  failGetCart?: boolean
  /** Fails add/update/remove while getCart keeps working — exercises the resync path. */
  failMutations?: boolean
  failPromo?: boolean
  catalog?: MockCatalogItem[]
  promos?: MockPromo[]
  /** Seed lines, applied through the same merge logic as addLine. */
  initialLines?: { sku: string; quantity: number }[]
  /** Flat rate the mock "server" applies after discount. Default 8%. */
  taxRate?: number
}

/**
 * Complete in-memory CartService — lets a consumer cart run e2e with no
 * backend (mock-first rule). Holds server-side cart state in a closure and
 * re-prices on every mutation, exactly like the real BFF contract. Failure
 * flags simulate outages so hosts can exercise error/resync paths
 * deterministically.
 */
export function createMockCartService(options: MockCartServiceOptions = {}): CartService {
  const catalog = options.catalog ?? DEFAULT_CATALOG
  const promos = options.promos ?? DEFAULT_PROMOS
  const taxRate = options.taxRate ?? 0.08
  const wait = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, options.latencyMs ?? 0))

  let lines: CartLineDTO[] = []
  let promoCode: string | null = null

  const addToCart = (sku: string, quantity: number): string | null => {
    const item = catalog.find((entry) => entry.sku === sku)
    if (!item) return `mock: unknown sku ${sku}`
    const existing = lines.find((line) => line.sku === sku)
    if (existing) {
      existing.quantity += quantity
    } else {
      lines.push({
        id: `line-${sku}`,
        sku: item.sku,
        name: item.name,
        ...(item.variant ? { variant: item.variant } : {}),
        quantity,
        unitPrice: item.unitPrice,
      })
    }
    return null
  }

  for (const seed of options.initialLines ?? []) addToCart(seed.sku, seed.quantity)

  const priced = (): CartDTO => {
    const subtotal = computeSubtotal(lines)
    const promo = promos.find((entry) => entry.code === promoCode)
    const discount = promo ? Math.round((subtotal * promo.percentOff) / 100) : 0
    const tax = Math.round((subtotal - discount) * taxRate)
    return {
      id: 'cart-mock',
      currency: 'USD',
      lines: lines.map((line) => ({ ...line })),
      promoCode,
      totals: { subtotal, discount, tax, total: subtotal - discount + tax },
    }
  }

  return {
    async getCart(_context) {
      await wait()
      if (options.failGetCart) return { status: 'error', errorMessage: 'mock: cart unavailable' }
      return { status: 'success', cart: priced() }
    },

    async addLine(_context, input) {
      await wait()
      if (options.failMutations) return { status: 'error', errorMessage: 'mock: cart mutation unavailable' }
      const issue = quantityIssue(input.quantity)
      if (issue) return { status: 'error', errorMessage: `mock: ${issue}` }
      const error = addToCart(input.sku, input.quantity)
      if (error) return { status: 'error', errorMessage: error }
      return { status: 'success', cart: priced() }
    },

    async updateLineQuantity(_context, input) {
      await wait()
      if (options.failMutations) return { status: 'error', errorMessage: 'mock: cart mutation unavailable' }
      const line = lines.find((entry) => entry.id === input.lineId)
      if (!line) return { status: 'error', errorMessage: `mock: unknown line ${input.lineId}` }
      const issue = quantityIssue(input.quantity)
      if (issue) return { status: 'error', errorMessage: `mock: ${issue}` }
      line.quantity = input.quantity
      return { status: 'success', cart: priced() }
    },

    async removeLine(_context, input) {
      await wait()
      if (options.failMutations) return { status: 'error', errorMessage: 'mock: cart mutation unavailable' }
      if (!lines.some((entry) => entry.id === input.lineId)) {
        return { status: 'error', errorMessage: `mock: unknown line ${input.lineId}` }
      }
      lines = lines.filter((entry) => entry.id !== input.lineId)
      return { status: 'success', cart: priced() }
    },

    async applyPromoCode(_context, input) {
      await wait()
      if (options.failPromo) return { status: 'error', errorMessage: 'mock: promo service unavailable' }
      const promo = promos.find((entry) => entry.code.toLowerCase() === input.code.trim().toLowerCase())
      if (!promo) {
        return { status: 'success', accepted: false, errorMessage: `"${input.code}" is not a valid promo code` }
      }
      promoCode = promo.code
      return { status: 'success', accepted: true, cart: priced() }
    },

    async removePromoCode(_context) {
      await wait()
      if (options.failPromo) return { status: 'error', errorMessage: 'mock: promo service unavailable' }
      promoCode = null
      return { status: 'success', cart: priced() }
    },
  }
}

/** Convenience RuntimeContext for demos and tests. */
export function createMockRuntimeContext(overrides: Partial<RuntimeContext> = {}): RuntimeContext {
  return {
    runtime: 'mock',
    identity: { organizationId: 'org-mock', accountId: 'acct-mock', ...overrides.identity },
    session: { origin: 'REACT_STOREFRONT', quoteId: 'quote-mock', ...overrides.session },
    ...(overrides.security ? { security: overrides.security } : {}),
    ...(overrides.runtime ? { runtime: overrides.runtime } : {}),
  }
}
