import { useId } from 'react'
import type { CartService } from '../core/port'
import type { RuntimeContext } from '../core/runtime'
import type { CartDTO, CartLineDTO } from '../core/types'
import { QUANTITY_MAX, formatMoney, lineTotal } from '../core/math'
import { useCartController } from './useCartController'
import type { CartController, CartControllerState } from '../ui-logic/cartController'

/* Icon stand-ins for the material-icons-outlined glyphs blink loads as a font
   (remove / add / close / shopping_cart) */

const MinusIcon = () => (
  <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true">
    <path d="M3 8h10" stroke="currentColor" strokeWidth="1.5" />
  </svg>
)

const PlusIcon = () => (
  <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true">
    <path d="M8 3v10M3 8h10" stroke="currentColor" strokeWidth="1.5" />
  </svg>
)

const CloseIcon = () => (
  <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true">
    <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.5" />
  </svg>
)

const CartLargeIcon = () => (
  <svg viewBox="0 0 24 24" width="36" height="36" aria-hidden="true">
    <path
      fill="currentColor"
      d="M7 18c-1.1 0-1.99.9-1.99 2S5.9 22 7 22s2-.9 2-2-.9-2-2-2zM1 2v2h2l3.6 7.59-1.35 2.45c-.16.28-.25.61-.25.96 0 1.1.9 2 2 2h12v-2H7.42c-.14 0-.25-.11-.25-.25l.03-.12.9-1.63h7.45c.75 0 1.41-.41 1.75-1.03l3.58-6.49c.08-.14.12-.31.12-.49 0-.55-.45-1-1-1H5.21l-.94-2H1zm16 16c-1.1 0-1.99.9-1.99 2s.89 2 1.99 2 2-.9 2-2-.9-2-2-2z"
    />
  </svg>
)

export interface CartPanelProps {
  context: RuntimeContext
  service: CartService
  onCartChange?: (cart: CartDTO) => void
  /** productList block header (blink cart page). */
  title?: string
  /** quoteSummary block header. */
  summaryTitle?: string
  debounceMs?: number
}

/**
 * Cart page replicating the blink storefront cart (TemplateRenderer blocks):
 * OrganismsProductListBlock (MoleculeDataTable + AtomButtonCounter + REMOVE),
 * OrganismsPromoCodeBlock, OrganismsQuoteSummaryBlock, and AtomEmptyCart.
 */
export function CartPanel(props: CartPanelProps) {
  const idBase = useId()
  const { state, controller } = useCartController({
    service: props.service,
    context: props.context,
    onCartChange: props.onCartChange,
    debounceMs: props.debounceMs,
  })

  const title = props.title ?? 'Shopping Cart'
  const summaryTitle = props.summaryTitle ?? 'Order Summary'
  const cart = state.cart
  const hasLines = cart !== null && cart.lines.length > 0
  const showImages = hasLines && cart.lines.some((line) => line.imageUrl)

  return (
    <div className="ec-cart">
      {state.errorMessage ? (
        <div role="alert" className="ec-cart__alert">
          <span>{state.errorMessage}</span>
        </div>
      ) : null}

      {state.loading ? <p className="ec-cart__hint">Loading…</p> : null}

      {!state.loading && cart && !hasLines ? (
        /* AtomEmptyCart */
        <div className="ec-cart__empty">
          <span className="ec-cart__empty-icon">
            <CartLargeIcon />
          </span>
          <p>Your cart is empty.</p>
        </div>
      ) : null}

      {!state.loading && cart && hasLines ? (
        <>
          {/* OrganismsProductListBlock */}
          <div className="ec-cart__prodlist">
            <div className="ec-cart__prodlist-header">
              <h3>{title}</h3>
            </div>
            <table className="ec-cart__table">
              <thead>
                <tr>
                  {showImages ? <th className="ec-cart__cell-img" /> : null}
                  <th>LINE DESCRIPTION</th>
                  <th>PRICE</th>
                  <th className="ec-cart__cell-center">QTY</th>
                  <th className="ec-cart__cell-right">TOTAL</th>
                  <th className="ec-cart__cell-actions" />
                </tr>
              </thead>
              <tbody>
                {cart.lines.map((line) => (
                  <Row
                    key={line.id}
                    line={line}
                    currency={cart.currency}
                    pending={state.pendingLineIds.includes(line.id)}
                    showImage={showImages}
                    onQuantity={(quantity) => controller.setLineQuantity(line.id, quantity)}
                    onRemove={() => void controller.removeLine(line.id)}
                  />
                ))}
              </tbody>
            </table>
            <div className="ec-cart__list-summary">
              <div className="ec-cart__list-summary-row">
                <span>Subtotal : </span>
                <span>{formatMoney(cart.totals.subtotal, cart.currency)}</span>
              </div>
            </div>
          </div>

          <div className="ec-cart__lower">
            <PromoBlock state={state} controller={controller} cart={cart} idBase={idBase} />

            {/* OrganismsQuoteSummaryBlock */}
            <div className="ec-cart__quote-summary">
              <div className="ec-cart__quote-summary-header">
                <h3>{summaryTitle}</h3>
              </div>
              <dl className="ec-cart__summary" data-testid="ec-cart-totals">
                <div className="ec-cart__summary-item">
                  <dt>Subtotal</dt>
                  <dd>{formatMoney(cart.totals.subtotal, cart.currency)}</dd>
                </div>
                {cart.totals.discount > 0 ? (
                  <div className="ec-cart__summary-item">
                    <dt>Discount</dt>
                    <dd>−{formatMoney(cart.totals.discount, cart.currency)}</dd>
                  </div>
                ) : null}
                <div className="ec-cart__summary-item">
                  <dt>Tax</dt>
                  <dd>{formatMoney(cart.totals.tax, cart.currency)}</dd>
                </div>
                <div className="ec-cart__summary-total">
                  <dt>Total</dt>
                  <dd>{formatMoney(cart.totals.total, cart.currency)}</dd>
                </div>
              </dl>
            </div>
          </div>
        </>
      ) : null}
    </div>
  )
}

interface RowProps {
  line: CartLineDTO
  currency: string
  pending: boolean
  showImage: boolean
  onQuantity: (quantity: number) => void
  onRemove: () => void
}

/* Table row mirrors MoleculeDataTable's desktop layout */
function Row({ line, currency, pending, showImage, onQuantity, onRemove }: RowProps) {
  return (
    <tr data-testid="ec-cart-line" data-pending={pending || undefined}>
      {showImage ? (
        <td className="ec-cart__cell-img">{line.imageUrl ? <img src={line.imageUrl} alt="" /> : null}</td>
      ) : null}
      <td>
        <p className="ec-cart__line-name">{line.name}</p>
        {line.variant ? <p className="ec-cart__line-variant">{line.variant}</p> : null}
      </td>
      <td>{formatMoney(line.unitPrice, currency)}</td>
      <td className="ec-cart__cell-center">
        <Counter line={line} pending={pending} onChange={onQuantity} />
      </td>
      <td className="ec-cart__cell-right">{formatMoney(lineTotal(line), currency)}</td>
      <td className="ec-cart__cell-actions">
        <button
          type="button"
          className="ec-cart__remove"
          aria-label={`Remove ${line.name}`}
          disabled={pending}
          onClick={onRemove}
        >
          REMOVE
        </button>
      </td>
    </tr>
  )
}

interface CounterProps {
  line: CartLineDTO
  pending: boolean
  onChange: (quantity: number) => void
}

/* AtomButtonCounter: − / × at qty 1, centered input (spinner while updating), + */
function Counter({ line, pending, onChange }: CounterProps) {
  return (
    <div className="ec-cart__counter">
      <button
        type="button"
        aria-label={`Decrease quantity of ${line.name}`}
        disabled={pending}
        onClick={() => onChange(line.quantity - 1)}
      >
        {line.quantity > 1 ? <MinusIcon /> : <CloseIcon />}
      </button>
      {pending ? (
        <span className="ec-cart__counter-spinner">
          <span className="ec-cart__spinner" aria-hidden="true" />
        </span>
      ) : (
        <input
          type="number"
          min={0}
          max={QUANTITY_MAX}
          step={1}
          value={line.quantity}
          aria-label={`Quantity of ${line.name}`}
          onKeyDown={(event) => {
            if (event.key === '.' || event.key === 'e' || event.key === 'E') event.preventDefault()
          }}
          onChange={(event) => {
            if (event.target.value !== '') onChange(Number(event.target.value))
          }}
        />
      )}
      <button
        type="button"
        aria-label={`Increase quantity of ${line.name}`}
        disabled={pending || line.quantity >= QUANTITY_MAX}
        onClick={() => onChange(line.quantity + 1)}
      >
        <PlusIcon />
      </button>
    </div>
  )
}

interface PromoBlockProps {
  state: CartControllerState
  controller: CartController
  cart: CartDTO
  idBase: string
}

/* OrganismsPromoCodeBlock: bordered box, label, input, APPLY/REMOVE theme buttons */
function PromoBlock({ state, controller, cart, idBase }: PromoBlockProps) {
  const applied = cart.promoCode

  return (
    <div className="ec-cart__promocode">
      <label className="ec-cart__promocode-label" htmlFor={`${idBase}-promo`}>
        Promo Code
      </label>
      <div className="ec-cart__promocode-input">
        <div className="ec-cart__promocode-box">
          <input
            id={`${idBase}-promo`}
            className="ec-cart__input"
            type="text"
            autoComplete="off"
            value={applied ?? state.promoInput}
            disabled={applied !== null}
            aria-invalid={state.promoError ? true : undefined}
            onChange={(event) => controller.setPromoInput(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !applied) void controller.applyPromo()
            }}
          />
          {state.promoError ? <p className="ec-cart__promocode-error">{state.promoError}</p> : null}
        </div>
        {state.applyingPromo ? (
          <span className="ec-cart__spinner" aria-hidden="true" />
        ) : applied ? (
          <button
            type="button"
            className="ec-cart__btn ec-cart__btn--secondary"
            onClick={() => void controller.removePromo()}
          >
            REMOVE
          </button>
        ) : (
          <button
            type="button"
            className="ec-cart__btn ec-cart__btn--primary"
            disabled={state.promoInput.trim().length < 1}
            onClick={() => void controller.applyPromo()}
          >
            APPLY
          </button>
        )}
        {applied && cart.totals.discount > 0 ? (
          <span className="ec-cart__promocode-success" data-testid="ec-cart-promo">
            Promo {applied} applied (−{formatMoney(cart.totals.discount, cart.currency)})
          </span>
        ) : null}
      </div>
    </div>
  )
}
