import type { CartService } from '../core/port'
import type { ApplyPromoCodeResult, CartResult } from '../core/types'

/**
 * The composable-core transport seam (Foundry-30845): a generic
 * Executor(method, payload). The host's runtime factory supplies a mock,
 * custom (BFF), or lwc implementation — this package never talks to a
 * network or to Salesforce directly. Pricing/tax/promo evaluation stays
 * behind the host BFF; no pricing engine is embedded.
 */
export type ComposableExecutor = (method: string, payload: Record<string, unknown>) => Promise<unknown>

export const CART_EXECUTOR_METHODS = {
  getCart: 'platform/cart:get',
  addLine: 'platform/cart:addLine',
  updateLineQuantity: 'platform/cart:updateLineQuantity',
  removeLine: 'platform/cart:removeLine',
  applyPromoCode: 'platform/cart:applyPromo',
  removePromoCode: 'platform/cart:removePromo',
} as const

const errorMessageOf = (error: unknown): string =>
  error instanceof Error ? error.message : 'Cart service request failed'

/** Wraps an executor as a CartService. Executor failures become `{ status: 'error' }` — never a rejection. */
export function createExecutorCartService(executor: ComposableExecutor): CartService {
  const call = async <T extends CartResult>(method: string, payload: Record<string, unknown>): Promise<T> => {
    try {
      return (await executor(method, payload)) as T
    } catch (error) {
      return { status: 'error', errorMessage: errorMessageOf(error) } as T
    }
  }

  return {
    getCart: (context) => call(CART_EXECUTOR_METHODS.getCart, { context }),
    addLine: (context, input) => call(CART_EXECUTOR_METHODS.addLine, { context, ...input }),
    updateLineQuantity: (context, input) =>
      call(CART_EXECUTOR_METHODS.updateLineQuantity, { context, ...input }),
    removeLine: (context, input) => call(CART_EXECUTOR_METHODS.removeLine, { context, ...input }),
    applyPromoCode: (context, input) =>
      call<ApplyPromoCodeResult>(CART_EXECUTOR_METHODS.applyPromoCode, { context, ...input }),
    removePromoCode: (context) => call(CART_EXECUTOR_METHODS.removePromoCode, { context }),
  }
}
