import type { CartService } from '../core/port'
import type { RuntimeContext } from '../core/runtime'
import type { CartDTO, MutationResult } from '../core/types'
import { QUANTITY_MAX, quantityIssue, withOptimisticTotals } from '../core/math'

export interface CartControllerState {
  /** True during the initial getCart (and refresh). */
  loading: boolean
  cart: CartDTO | null
  /** Lines with an in-flight quantity/remove mutation — the UI disables their controls. */
  pendingLineIds: string[]
  addingSku: string | null
  promoInput: string
  applyingPromo: boolean
  promoError: string | null
  errorMessage: string | null
}

export interface CartControllerCallbacks {
  /** Fires with every server-confirmed cart. Optimistic states stay UI-local. */
  onCartChange?: (cart: CartDTO) => void
}

export interface CartControllerOptions extends CartControllerCallbacks {
  service: CartService
  context: RuntimeContext
  /** Coalesces rapid quantity-stepper clicks into one mutation per line. */
  debounceMs?: number
}

export interface CartController {
  getState(): CartControllerState
  subscribe(listener: () => void): () => void
  setCallbacks(callbacks: CartControllerCallbacks): void
  /** Loads the cart. */
  init(): Promise<void>
  /** Re-fetches the cart — hosts call this after out-of-band mutations (e.g. PDP add-to-cart). */
  refresh(): Promise<void>
  addLine(sku: string, quantity?: number): Promise<MutationResult>
  /** Optimistic, coalesced per line by debounceMs. Quantity <= 0 removes the line. */
  setLineQuantity(lineId: string, quantity: number): void
  /** Awaitable variant for edit-form UIs — pushes immediately, no optimistic state. Quantity <= 0 removes the line. */
  updateLineQuantity(lineId: string, quantity: number): Promise<MutationResult>
  removeLine(lineId: string): Promise<MutationResult>
  setPromoInput(code: string): void
  applyPromo(): Promise<MutationResult>
  removePromo(): Promise<MutationResult>
  dispose(): void
}

const initialState = (): CartControllerState => ({
  loading: false,
  cart: null,
  pendingLineIds: [],
  addingSku: null,
  promoInput: '',
  applyingPromo: false,
  promoError: null,
  errorMessage: null,
})

export function createCartController(options: CartControllerOptions): CartController {
  const { service, context } = options
  const debounceMs = options.debounceMs ?? 300
  let callbacks: CartControllerCallbacks = { onCartChange: options.onCartChange }

  let state = initialState()
  const listeners = new Set<() => void>()
  const quantityTimers = new Map<string, ReturnType<typeof setTimeout>>()
  const quantitySeq = new Map<string, number>()

  const setState = (patch: Partial<CartControllerState>): void => {
    state = { ...state, ...patch }
    for (const listener of listeners) listener()
  }

  const markPending = (lineId: string): void => {
    if (!state.pendingLineIds.includes(lineId)) {
      setState({ pendingLineIds: [...state.pendingLineIds, lineId] })
    }
  }

  const clearPending = (lineId: string): void => {
    setState({ pendingLineIds: state.pendingLineIds.filter((id) => id !== lineId) })
  }

  const commitCart = (cart: CartDTO): void => {
    setState({ cart, errorMessage: null })
    callbacks.onCartChange?.(cart)
  }

  /**
   * A failed optimistic mutation re-syncs from the server so the displayed
   * cart never drifts from what the host will charge. If the re-sync also
   * fails, the last known server cart stays on screen.
   */
  const resync = async (errorMessage: string): Promise<void> => {
    const result = await service.getCart(context)
    setState({
      errorMessage,
      cart: result.status === 'success' && result.cart ? result.cart : state.cart,
    })
  }

  const load = async (): Promise<void> => {
    setState({ loading: true })
    const result = await service.getCart(context)
    setState({ loading: false })
    if (result.status === 'error' || !result.cart) {
      setState({ errorMessage: result.errorMessage ?? 'Could not load your cart.' })
      return
    }
    commitCart(result.cart)
  }

  const bumpSeq = (lineId: string): number => {
    const seq = (quantitySeq.get(lineId) ?? 0) + 1
    quantitySeq.set(lineId, seq)
    return seq
  }

  const pushQuantity = async (lineId: string, quantity: number): Promise<MutationResult> => {
    const seq = bumpSeq(lineId)
    markPending(lineId)
    const result = await service.updateLineQuantity(context, { lineId, quantity })
    if (quantitySeq.get(lineId) !== seq) return { status: 'success' } // superseded — the newer call owns the state
    clearPending(lineId)
    if (result.status === 'error' || !result.cart) {
      const errorMessage = result.errorMessage ?? 'Could not update the quantity — your cart has been refreshed.'
      await resync(errorMessage)
      return { status: 'error', errorMessage }
    }
    commitCart(result.cart)
    return { status: 'success' }
  }

  const flushQuantity = async (lineId: string): Promise<void> => {
    const quantity = state.cart?.lines.find((line) => line.id === lineId)?.quantity
    if (quantity === undefined) return
    await pushQuantity(lineId, quantity)
  }

  const removeLine = async (lineId: string): Promise<MutationResult> => {
    const timer = quantityTimers.get(lineId)
    if (timer) {
      clearTimeout(timer)
      quantityTimers.delete(lineId)
    }
    bumpSeq(lineId) // cancel any in-flight quantity flush for this line
    markPending(lineId)
    const result = await service.removeLine(context, { lineId })
    clearPending(lineId)
    if (result.status === 'error' || !result.cart) {
      const errorMessage = result.errorMessage ?? 'Could not remove the item — your cart has been refreshed.'
      await resync(errorMessage)
      return { status: 'error', errorMessage }
    }
    commitCart(result.cart)
    return { status: 'success' }
  }

  return {
    getState: () => state,

    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },

    setCallbacks(next) {
      callbacks = next
    },

    init: load,
    refresh: load,

    async addLine(sku, quantity = 1) {
      const issue = quantityIssue(quantity)
      if (issue) return { status: 'error', errorMessage: issue }
      setState({ addingSku: sku })
      const result = await service.addLine(context, { sku, quantity })
      setState({ addingSku: null })
      if (result.status === 'error' || !result.cart) {
        const errorMessage = result.errorMessage ?? 'Could not add the item to your cart.'
        setState({ errorMessage })
        return { status: 'error', errorMessage }
      }
      commitCart(result.cart)
      return { status: 'success' }
    },

    setLineQuantity(lineId, quantity) {
      const cart = state.cart
      if (!cart || !cart.lines.some((line) => line.id === lineId)) return
      if (quantity <= 0) {
        void removeLine(lineId)
        return
      }
      const clamped = Math.min(quantity, QUANTITY_MAX)
      if (quantityIssue(clamped)) return // non-integer input — ignore
      const lines = cart.lines.map((line) => (line.id === lineId ? { ...line, quantity: clamped } : line))
      setState({ cart: withOptimisticTotals({ ...cart, lines }) })
      const timer = quantityTimers.get(lineId)
      if (timer) clearTimeout(timer)
      quantityTimers.set(
        lineId,
        setTimeout(() => {
          quantityTimers.delete(lineId)
          void flushQuantity(lineId)
        }, debounceMs),
      )
    },

    async updateLineQuantity(lineId, quantity) {
      const cart = state.cart
      if (!cart || !cart.lines.some((line) => line.id === lineId)) {
        return { status: 'error', errorMessage: 'Line not found' }
      }
      if (quantity <= 0) return removeLine(lineId)
      const issue = quantityIssue(quantity)
      if (issue) return { status: 'error', errorMessage: issue }
      const timer = quantityTimers.get(lineId)
      if (timer) {
        clearTimeout(timer)
        quantityTimers.delete(lineId)
      }
      return pushQuantity(lineId, quantity)
    },

    removeLine,

    setPromoInput(code) {
      setState({ promoInput: code, promoError: null })
    },

    async applyPromo() {
      const code = state.promoInput.trim()
      if (!code) {
        const errorMessage = 'Enter a promo code'
        setState({ promoError: errorMessage })
        return { status: 'error', errorMessage }
      }
      setState({ applyingPromo: true, promoError: null })
      const result = await service.applyPromoCode(context, { code })
      setState({ applyingPromo: false })
      if (result.status === 'error' || result.accepted === false || !result.cart) {
        const errorMessage = result.errorMessage ?? 'This promo code could not be applied.'
        setState({ promoError: errorMessage })
        return { status: 'error', errorMessage }
      }
      setState({ promoInput: '' })
      commitCart(result.cart)
      return { status: 'success' }
    },

    async removePromo() {
      setState({ applyingPromo: true, promoError: null })
      const result = await service.removePromoCode(context)
      setState({ applyingPromo: false })
      if (result.status === 'error' || !result.cart) {
        const errorMessage = result.errorMessage ?? 'Could not remove the promo code.'
        setState({ promoError: errorMessage })
        return { status: 'error', errorMessage }
      }
      commitCart(result.cart)
      return { status: 'success' }
    },

    dispose() {
      for (const timer of quantityTimers.values()) clearTimeout(timer)
      quantityTimers.clear()
    },
  }
}
