import type { CartDTO, CartLineDTO } from './types'

export const QUANTITY_MIN = 1
export const QUANTITY_MAX = 99

/** Offline quantity check — steppers clamp, but hosts may pass arbitrary values. */
export function quantityIssue(quantity: number): string | null {
  if (!Number.isInteger(quantity)) return 'Quantity must be a whole number'
  if (quantity < QUANTITY_MIN) return `Quantity must be at least ${QUANTITY_MIN}`
  if (quantity > QUANTITY_MAX) return `Quantity cannot exceed ${QUANTITY_MAX}`
  return null
}

/** Line price in minor units. */
export const lineTotal = (line: CartLineDTO): number => line.unitPrice * line.quantity

export const computeSubtotal = (lines: CartLineDTO[]): number =>
  lines.reduce((sum, line) => sum + lineTotal(line), 0)

/**
 * Display-only approximation while a mutation is in flight: subtotal is
 * recomputed from the lines; discount/tax keep their last server values.
 * The next server response replaces the whole cart — this never becomes
 * an authoritative total.
 */
export function withOptimisticTotals(cart: CartDTO): CartDTO {
  const subtotal = computeSubtotal(cart.lines)
  const totals = {
    ...cart.totals,
    subtotal,
    total: subtotal - cart.totals.discount + cart.totals.tax,
  }
  return { ...cart, totals }
}

/** Minor units → localized currency string (2999, 'USD' → "$29.99"). */
export function formatMoney(amountMinor: number, currency: string): string {
  return new Intl.NumberFormat('en', { style: 'currency', currency }).format(amountMinor / 100)
}

/** Total item count across lines (mini-cart badge). */
export const cartItemCount = (cart: CartDTO | null): number =>
  cart ? cart.lines.reduce((sum, line) => sum + line.quantity, 0) : 0
