import { useEffect, useRef, useSyncExternalStore } from 'react'
import { createCartController } from '../ui-logic/cartController'
import type {
  CartController,
  CartControllerOptions,
  CartControllerState,
} from '../ui-logic/cartController'

export interface UseCartControllerResult {
  state: CartControllerState
  controller: CartController
}

/**
 * Binds a CartController to React. The controller is created once per
 * mount; callbacks are kept fresh across renders via setCallbacks.
 */
export function useCartController(options: CartControllerOptions): UseCartControllerResult {
  const controllerRef = useRef<CartController | null>(null)
  controllerRef.current ??= createCartController(options)
  const controller = controllerRef.current

  const { onCartChange } = options
  useEffect(() => {
    controller.setCallbacks({ onCartChange })
  }, [controller, onCartChange])

  useEffect(() => {
    void controller.init()
    return () => {
      controller.dispose()
    }
  }, [controller])

  const state = useSyncExternalStore(controller.subscribe, controller.getState, controller.getState)
  return { state, controller }
}
